<template>
  <a-modal :open="open" title="公司行动管理" width="900px" :footer="null" @cancel="emit('update:open', false)">
    <a-alert type="info" show-icon style="margin-bottom:16px" message="公司行动会独立保存并自动重算持仓、成本、现金与收益，不会生成 0 元买卖或手续费。" />
    <a-form layout="inline" :model="form" style="margin-bottom:12px">
      <a-form-item><a-input v-model:value="form.symbol" placeholder="证券代码" /></a-form-item><a-form-item><a-input v-model:value="form.name" placeholder="证券名称" /></a-form-item>
      <a-form-item><a-select v-model:value="form.type" style="width:130px"><a-select-option v-for="t in types" :key="t.value" :value="t.value">{{ t.label }}</a-select-option></a-select></a-form-item>
      <a-form-item><a-date-picker v-model:value="form.date" value-format="YYYY-MM-DD" /></a-form-item><a-form-item><a-select v-model:value="form.currency" style="width:80px"><a-select-option value="CNY">CNY</a-select-option><a-select-option value="HKD">HKD</a-select-option><a-select-option value="USD">USD</a-select-option></a-select></a-form-item>
    </a-form>
    <a-form layout="inline" :model="form" style="margin-bottom:16px">
      <a-form-item v-if="ratio"><a-input-number v-model:value="form.ratioNumerator" :min="0.000001" placeholder="拆分后" /></a-form-item><a-form-item v-if="ratio">:</a-form-item><a-form-item v-if="ratio"><a-input-number v-model:value="form.ratioDenominator" :min="0.000001" placeholder="拆分前" /></a-form-item>
      <a-form-item v-if="quantity"><a-input-number v-model:value="form.quantityChange" :min="0.000001" placeholder="增加份额" /></a-form-item><a-form-item v-if="cash"><a-input-number v-model:value="form.cashAmount" :min="0.01" placeholder="金额/现金支出" /></a-form-item>
      <a-form-item><a-input v-model:value="form.sourceId" placeholder="来源标识（防重复）" /></a-form-item><a-form-item><a-button type="primary" :loading="saving" @click="save">{{ editingId ? '保存' : '新增' }}</a-button><a-button v-if="editingId" style="margin-left:8px" @click="reset">取消</a-button></a-form-item>
    </a-form>
    <a-table :data-source="actions" :columns="columns" :loading="loading" :pagination="false" row-key="_id" size="small"><template #bodyCell="{ column, record }"><template v-if="column.key === 'date'">{{ String(record.date).slice(0,10) }}</template><template v-else-if="column.key === 'type'">{{ label(record.type) }}</template><template v-else-if="column.key === 'detail'">{{ detail(record) }}</template><template v-else-if="column.key === 'operation'"><a-button type="link" size="small" @click="edit(record)">编辑</a-button><a-popconfirm title="确定删除并自动重算统计？" @confirm="remove(record)"><a-button type="link" danger size="small">删除</a-button></a-popconfirm></template></template></a-table>
  </a-modal>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { message } from 'ant-design-vue';
import { createCorporateAction, deleteCorporateAction, getCorporateActions, updateCorporateAction } from '@/api/index';
const props = defineProps({ open: Boolean }); const emit = defineEmits(['update:open', 'changed']); const loading=ref(false), saving=ref(false), actions=ref([]), editingId=ref(null);
const types=[{value:'CASH_DIVIDEND',label:'现金分红'},{value:'SPLIT',label:'拆分'},{value:'REVERSE_SPLIT',label:'合并'},{value:'STOCK_DIVIDEND',label:'送股'},{value:'BONUS_ISSUE',label:'转增'},{value:'RIGHTS_ISSUE',label:'配股/供股'}]; const columns=[{title:'日期',key:'date'},{title:'证券',dataIndex:'symbol'},{title:'名称',dataIndex:'name'},{title:'类型',key:'type'},{title:'明细',key:'detail'},{title:'来源',dataIndex:'sourceId'},{title:'操作',key:'operation'}];
const init=()=>({symbol:'',name:'',type:'CASH_DIVIDEND',date:'',currency:'CNY',cashAmount:null,quantityChange:null,ratioNumerator:null,ratioDenominator:null,sourceId:'',remark:''}); const form=reactive(init()); const ratio=computed(()=>['SPLIT','REVERSE_SPLIT'].includes(form.type)); const quantity=computed(()=>['STOCK_DIVIDEND','BONUS_ISSUE','RIGHTS_ISSUE'].includes(form.type)); const cash=computed(()=>['CASH_DIVIDEND','RIGHTS_ISSUE'].includes(form.type));
const load=async()=>{loading.value=true;try{actions.value=(await getCorporateActions()).list||[]}catch{message.error('读取失败')}finally{loading.value=false}}; const reset=()=>{Object.assign(form,init());editingId.value=null}; const save=async()=>{if(!form.symbol||!form.name||!form.date||!form.sourceId)return message.warning('请填写证券、名称、日期和来源标识');saving.value=true;try{const data={...form,cashAmount:Number(form.cashAmount||0),quantityChange:Number(form.quantityChange||0)}; editingId.value?await updateCorporateAction(editingId.value,data):await createCorporateAction(data);message.success('已保存并自动重算');reset();await load();emit('changed')}catch(e){message.error(e?.message||'保存失败')}finally{saving.value=false}}; const edit=r=>{editingId.value=r._id;Object.assign(form,{...init(),...r,date:String(r.date).slice(0,10)})}; const remove=async r=>{try{await deleteCorporateAction(r._id);message.success('已删除并自动重算');await load();emit('changed')}catch{message.error('删除失败')}}; const label=t=>types.find(x=>x.value===t)?.label||t; const detail=a=>ratioType(a.type)?`${a.ratioDenominator}:${a.ratioNumerator}`:a.type==='RIGHTS_ISSUE'?`+${a.quantityChange}，支出 ${a.cashAmount} ${a.currency}`:a.type==='CASH_DIVIDEND'?`${a.cashAmount} ${a.currency}`:`+${a.quantityChange}`; const ratioType=t=>['SPLIT','REVERSE_SPLIT'].includes(t); watch(()=>props.open,v=>{if(v)load()});
</script>
